import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^\d+$/;

function dateOf(value: unknown, label: string): string {
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) YYYY-MM-DD 형식으로 입력하세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01804Controller {
  @Post('/attendance-closings/aggregate')
  @HttpCode(200)
  async aggregateAttendanceClosings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const startDate = dateOf(data['closingStartDate'], '마감 시작일');
    const endDate = dateOf(data['closingEndDate'], '마감 종료일');
    return transaction(async (db) => {
      const valid = await db.query(
        'SELECT (CAST(:endDate AS date) >= CAST(:startDate AS date)) AS "ok"',
        { startDate, endDate },
      );
      if (!valid[0] || valid[0]['ok'] !== true) {
        throw new ApiError(422, 'INVALID_CLOSING_PERIOD', '마감 대상 기간이 올바르지 않습니다.');
      }
      const rows = await db.query(
        `SELECT COUNT(*) AS "totalCount",
                COUNT(*) FILTER (WHERE closing_status <> '승인') AS "unprocessedCount"
           FROM attendance_daily
          WHERE work_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)`,
        { startDate, endDate },
      );
      return {
        totalCount: Number(rows[0]['totalCount']),
        unprocessedCount: Number(rows[0]['unprocessedCount']),
      };
    });
  }

  @Post('/attendance-closings')
  @HttpCode(200)
  async closeAttendance(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const startDate = dateOf(data['closingStartDate'], '마감 시작일');
    const endDate = dateOf(data['closingEndDate'], '마감 종료일');
    return transaction(async (db) => {
      const valid = await db.query(
        'SELECT (CAST(:endDate AS date) >= CAST(:startDate AS date)) AS "ok"',
        { startDate, endDate },
      );
      if (!valid[0] || valid[0]['ok'] !== true) {
        throw new ApiError(400, 'VALIDATION_FAILED', '마감 종료일은 시작일보다 빠를 수 없습니다.');
      }
      const counts = await db.query(
        `SELECT COUNT(*) FILTER (WHERE closing_status = '마감') AS "closedCount",
                COUNT(*) FILTER (WHERE closing_status <> '승인' AND closing_status <> '마감') AS "unprocessedCount"
           FROM attendance_daily
          WHERE work_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)`,
        { startDate, endDate },
      );
      if (Number(counts[0]['closedCount']) > 0) {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 일자가 포함되어 있습니다.');
      }
      // 가정: 승인이 아닌 근태가 하나라도 있으면 마감을 거부한다.
      if (Number(counts[0]['unprocessedCount']) > 0) {
        throw new ApiError(422, 'UNAPPROVED_ATTENDANCE_EXISTS', '미승인 또는 미처리 근태가 있어 마감할 수 없습니다.');
      }
      const existing = await db.query(
        `SELECT attendance_closing_id AS "attendanceClosingId", closing_status AS "closingStatus"
           FROM attendance_closing
          WHERE employee_id = CAST(:userId AS bigint)
            AND closing_start_date = CAST(:startDate AS date)
            AND closing_end_date = CAST(:endDate AS date)`,
        { userId: user.id, startDate, endDate },
      );
      if (existing.length > 0) {
        if (existing[0]['closingStatus'] === '마감') {
          throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 기간입니다.');
        }
        const updated = await db.query(
          `UPDATE attendance_closing
              SET closing_status = '마감', processed_at = now(), updated_at = now()
            WHERE attendance_closing_id = CAST(:id AS bigint)
        RETURNING attendance_closing_id AS "attendanceClosingId", closing_status AS "closingStatus"`,
          { id: String(existing[0]['attendanceClosingId']) },
        );
        return updated[0];
      }
      const rows = await db.query(
        `INSERT INTO attendance_closing
           (employee_id, closing_start_date, closing_end_date, closing_status, processed_at, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:startDate AS date), CAST(:endDate AS date), '마감', now(), now(), now())
         RETURNING attendance_closing_id AS "attendanceClosingId", closing_status AS "closingStatus"`,
        { userId: user.id, startDate, endDate },
      );
      return rows[0];
    });
  }

  @Post('/attendance-closings/:attendanceClosingId/cancel')
  @HttpCode(200)
  async cancelAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const id = req.params['attendanceClosingId'];
    if (!ID_PATTERN.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 마감 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM attendance_closing
          WHERE attendance_closing_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_CLOSING_NOT_FOUND', '근태 마감 건을 찾을 수 없습니다.');
      }
      if (found[0]['closingStatus'] !== '마감') {
        throw new ApiError(409, 'ATTENDANCE_NOT_CLOSED', '마감 상태가 아닌 건은 취소할 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE attendance_closing
            SET closing_status = '마감취소', processed_at = now(), updated_at = now()
          WHERE attendance_closing_id = CAST(:id AS bigint)
      RETURNING closing_status AS "closingStatus"`,
        { id },
      );
      return rows[0];
    });
  }

  @Post('/attendance-dailies/close')
  @HttpCode(200)
  async closeAttendanceDailies(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const workDate = dateOf(data['workDate'], '근무일자');
    return transaction(async (db) => {
      const counts = await db.query(
        `SELECT COUNT(*) AS "totalCount",
                COUNT(*) FILTER (WHERE closing_status = '마감') AS "closedCount",
                COUNT(*) FILTER (WHERE closing_status <> '승인' AND closing_status <> '마감') AS "unprocessedCount"
           FROM attendance_daily
          WHERE work_date = CAST(:workDate AS date)`,
        { workDate },
      );
      if (Number(counts[0]['totalCount']) === 0) {
        throw new ApiError(404, 'NOT_FOUND', '해당 일자의 근태 기록이 없습니다.');
      }
      if (Number(counts[0]['closedCount']) > 0) {
        throw new ApiError(409, 'ATTENDANCE_DAILY_ALREADY_CLOSED', '이미 마감된 일자입니다.');
      }
      // 가정: 승인이 아닌 근태가 하나라도 있으면 마감을 거부한다.
      if (Number(counts[0]['unprocessedCount']) > 0) {
        throw new ApiError(422, 'UNAPPROVED_ATTENDANCE_EXISTS', '미승인 또는 미처리 근태가 있어 마감할 수 없습니다.');
      }
      await db.execute(
        `UPDATE attendance_daily
            SET closing_status = '마감', updated_at = now()
          WHERE work_date = CAST(:workDate AS date)`,
        { workDate },
      );
      return { closingStatus: '마감' };
    });
  }

  @Post('/attendance-dailies/cancel-close')
  @HttpCode(200)
  async cancelCloseAttendanceDailies(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const workDate = dateOf(data['workDate'], '근무일자');
    return transaction(async (db) => {
      const changed = await db.execute(
        `UPDATE attendance_daily
            SET closing_status = '마감취소', updated_at = now()
          WHERE work_date = CAST(:workDate AS date)
            AND closing_status = '마감'`,
        { workDate },
      );
      if (changed === 0) {
        throw new ApiError(409, 'ATTENDANCE_DAILY_NOT_CLOSED', '마감 상태가 아닌 일자는 취소할 수 없습니다.');
      }
      return { closingStatus: '마감취소' };
    });
  }
}

