import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  Num,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = '' | 'aggregate' | 'close' | 'dailyClose' | 'dailyCancel';

export default function FnSfr01804Page({ role, notify }: PageProps) {
  const [mode, setMode] = useState<Mode>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [workDate, setWorkDate] = useState('');
  const [summary, setSummary] = useState<Row | undefined>(undefined);
  const [closings, setClosings] = useState<Row[]>([]);
  const [dailies, setDailies] = useState<Row[]>([]);

  function open(next: Mode) {
    setMode(next);
  }

  function checkPeriod() {
    if (!startDate || !endDate) {
      throw new Error('마감 시작일과 마감 종료일을 입력하세요.');
    }
    if (endDate < startDate) {
      throw new Error('마감 종료일은 시작일보다 빠를 수 없습니다.');
    }
  }

  function checkWorkDate() {
    if (!workDate) {
      throw new Error('근무일자를 입력하세요.');
    }
  }

  async function aggregate() {
    checkPeriod();
    const result = await call('POST', '/attendance-closings/aggregate', role, {
      closingStartDate: startDate,
      closingEndDate: endDate,
    });
    setSummary(result);
    setMode('');
    notify('근태 결과를 집계했습니다.');
  }

  async function closePeriod() {
    checkPeriod();
    const result = await call('POST', '/attendance-closings', role, {
      closingStartDate: startDate,
      closingEndDate: endDate,
    });
    setClosings([
      {
        attendanceClosingId: result['attendanceClosingId'],
        closingStartDate: startDate,
        closingEndDate: endDate,
        closingStatus: result['closingStatus'],
      },
      ...closings.filter((c) => c['attendanceClosingId'] !== result['attendanceClosingId']),
    ]);
    setMode('');
    notify('근태를 마감했습니다.');
  }

  async function cancelClosing(row: Row) {
    const result = await call('POST', '/attendance-closings/' + String(row['attendanceClosingId']) + '/cancel', role);
    setClosings(
      closings.map((c) =>
        c['attendanceClosingId'] === row['attendanceClosingId']
          ? { ...c, closingStatus: result['closingStatus'] }
          : c,
      ),
    );
    notify('근태 마감을 취소했습니다.');
  }

  async function closeDaily() {
    checkWorkDate();
    const result = await call('POST', '/attendance-dailies/close', role, { workDate });
    setDailies([
      { workDate, closingStatus: result['closingStatus'] },
      ...dailies.filter((d) => d['workDate'] !== workDate),
    ]);
    setMode('');
    notify('일별 근태를 마감했습니다.');
  }

  async function cancelDaily() {
    checkWorkDate();
    const result = await call('POST', '/attendance-dailies/cancel-close', role, { workDate });
    setDailies([
      { workDate, closingStatus: result['closingStatus'] },
      ...dailies.filter((d) => d['workDate'] !== workDate),
    ]);
    setMode('');
    notify('일별 근태 마감을 취소했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>집계 현황</h2>
        <Tiles
          items={[
            ['집계 대상 근태 건수', summary ? <Num value={summary['totalCount']} /> : '-'],
            ['미승인 또는 미처리 건수', summary ? <Num value={summary['unprocessedCount']} /> : '-'],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>기간 마감</h2>
        <Band total={closings.length}>
          <button type="button" onClick={() => open('aggregate')}>집계</button>
          <button type="button" onClick={() => open('close')}>기간 마감</button>
        </Band>
        <DataTable
          rows={closings}
          empty="처리한 마감 내역이 없습니다."
          columns={[
            { key: 'closingStartDate', label: '마감 시작일', render: (r) => <DateText value={r['closingStartDate']} /> },
            { key: 'closingEndDate', label: '마감 종료일', render: (r) => <DateText value={r['closingEndDate']} /> },
            { key: 'closingStatus', label: '마감·승인 처리 상태', render: (r) => <Badge value={r['closingStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['closingStatus'] === '마감' ? (
                  <button type="button" onClick={() => cancelClosing(r)}>마감취소</button>
                ) : null,
            },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>일별 마감</h2>
        <Band total={dailies.length}>
          <button type="button" onClick={() => open('dailyClose')}>일별 마감</button>
          <button type="button" onClick={() => open('dailyCancel')}>일별 마감취소</button>
        </Band>
        <DataTable
          rows={dailies}
          empty="처리한 일자가 없습니다."
          columns={[
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r['workDate']} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
          ]}
        />
      </section>
      {mode === 'aggregate' && (
        <Drawer title="근태 결과 집계" onClose={() => setMode('')}>
          <Form onSubmit={aggregate} submit="집계">
            <Field label="마감 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="마감 종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'close' && (
        <Drawer title="기간 근태 마감" onClose={() => setMode('')}>
          <Form onSubmit={closePeriod} submit="마감">
            <Field label="마감 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="마감 종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'dailyClose' && (
        <Drawer title="일별 근태 마감" onClose={() => setMode('')}>
          <Form onSubmit={closeDaily} submit="마감">
            <Field label="근무일자" required>
              <DateInput value={workDate} onChange={setWorkDate} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'dailyCancel' && (
        <Drawer title="일별 근태 마감취소" onClose={() => setMode('')}>
          <Form onSubmit={cancelDaily} submit="마감취소" danger>
            <Field label="근무일자" required>
              <DateInput value={workDate} onChange={setWorkDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
